window.HOEREN_TESTS[31] = {"id":"im-schwimmbad","name":"Im Schwimmbad","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Liebe Schwimmer, das Hallenbad schließt heute schon um 19 Uhr, statt um 22 Uhr, wegen einer Wartung. Um 18 Uhr müssen Sie noch nicht gehen, Sie haben noch eine Stunde Zeit. Morgen sind wir wieder zu normalen Zeiten geöffnet, von 7 bis 22 Uhr. Wir entschuldigen uns für die kurzfristige Schließung.","gender":"f","q":"Wann schließt das Schwimmbad heute?","opts":["Um 18 Uhr.","Um 22 Uhr.","Um 19 Uhr."],"correct":2},{"transcript":"Hallo Frau Wagner, hier ist die Schwimmschule. Ihr Sohn Tim: sein Anfänger-Kurs beginnt am 10. April, nicht am 1. wie ursprünglich, das Startdatum hat sich also geändert. Der Lehrer bleibt gleich, und der Ort auch, wir sind im Hallenbad. Bitte bringen Sie Schwimmsachen und ein Handtuch mit, auch eine Mütze brauchen wir.","gender":"m","q":"Was hat sich geändert?","opts":["Das Startdatum.","Der Ort.","Der Lehrer."],"correct":0},{"transcript":"Achtung an alle Besucher: Das Sprungbecken ist heute geschlossen, weil wir das Sprungbrett reparieren. Sie können aber das große Becken nutzen, und das Kinderbecken auch ganz normal. Morgen sollte das Sprungbecken wieder offen sein. Vielen Dank für Ihr Verständnis und einen schönen Tag im Wasser.","gender":"f","q":"Was ist heute zu?","opts":["Das große Becken.","Das Kinderbecken.","Das Sprungbecken."],"correct":2},{"transcript":"Hi Sara, hier ist Anna. Wegen unseres Schwimmtreffens morgen: Wir gehen nicht ins normale Hallenbad, sondern ins neue Aqua-Center am Stadtrand. An den See fahren wir diesmal nicht, das Wasser ist noch zu kalt. Das Aqua-Center hat mehr Becken und Rutschen, soll sehr schön sein. Treffpunkt 14 Uhr direkt vor dem Eingang.","gender":"f","q":"Wohin gehen sie morgen?","opts":["Ins normale Hallenbad.","Ins Aqua-Center am Stadtrand.","An den See."],"correct":1},{"transcript":"Liebe Eltern, eine Information für unseren Wassertag in der Schule. Bitte geben Sie Ihren Kindern Sportkleidung mit, Badeanzug oder Badehose, ein Handtuch und Sonnencreme. Auch ein Snack ist gut, wir sind den ganzen Vormittag draußen. Den Eintritt zahlt die Schule, Sie müssen nichts zahlen. Die Sonnencreme bringen Sie bitte selbst mit.","gender":"m","q":"Was müssen Eltern bezahlen?","opts":["Den Eintritt.","Nichts.","Die Sonnencreme."],"correct":1}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch. Sie hören den Text einmal. Was machen sie an welchem Tag? Wählen Sie für jeden Tag einen Buchstaben (a–i).","lines":[{"speaker":"Vater","gender":"m","text":"Hallo! Das Schwimmbad hat diese Woche jeden Tag geöffnet."},{"speaker":"Mutter","gender":"f","text":"Dann verteilen wir die Sachen auf fünf Tage."},{"speaker":"Vater","gender":"m","text":"Wir schwimmen montags Bahnen. Zwanzig Stück schaffen wir in Ruhe."},{"speaker":"Mutter","gender":"f","text":"Danach bist du müde und richtig zufrieden."},{"speaker":"Vater","gender":"m","text":"Spielt die Gruppe am Abend auch Wasserball?"},{"speaker":"Mutter","gender":"f","text":"Nein. Wasserball spielen sie nicht."},{"speaker":"Vater","gender":"m","text":"Der nächste Morgen gehört deiner Gruppe im Wasser."},{"speaker":"Mutter","gender":"f","text":"Ich mache am Dienstag Aqua-Fitness. Um neun ist die Halle noch leer."},{"speaker":"Vater","gender":"m","text":"Lisa hat am Mittwoch frei von der Schule."},{"speaker":"Mutter","gender":"f","text":"Dann rutscht sie auf der Wasserrutsche. Am Nachmittag bleibt sie im Bad."},{"speaker":"Vater","gender":"m","text":"Tim traut sich noch nicht ins tiefe Wasser."},{"speaker":"Mutter","gender":"f","text":"Er geht am Donnerstag in den Schwimmkurs. Der Lehrer wartet an der Treppe."},{"speaker":"Vater","gender":"m","text":"Springt noch jemand vom Sprungbrett?"},{"speaker":"Mutter","gender":"f","text":"Nein. Vom Sprungbrett springt auch keiner."},{"speaker":"Vater","gender":"m","text":"Zum Schluss der Woche wollen Anna und Markus es warm haben."},{"speaker":"Mutter","gender":"f","text":"Die beiden gehen am Freitag in die Sauna. Danach sitzen sie still im Ruheraum."},{"speaker":"Vater","gender":"m","text":"Ich schreibe die fünf Tage auf einen Zettel."},{"speaker":"Mutter","gender":"f","text":"Leg ihn in die Sporttasche. Morgen früh geht es los."}],"options":[{"letter":"a","text":"rutscht auf der Wasserrutsche"},{"letter":"b","text":"trinkt etwas im Café"},{"letter":"c","text":"geht in die Sauna"},{"letter":"d","text":"liegt am Beckenrand"},{"letter":"e","text":"macht Aqua-Fitness"},{"letter":"f","text":"geht in den Schwimmkurs"},{"letter":"g","text":"schwimmt Bahnen"},{"letter":"h","text":"springt vom Sprungbrett"},{"letter":"i","text":"spielt Wasserball"}],"items":[{"person":"Montag","correct":"g"},{"person":"Dienstag","correct":"e"},{"person":"Mittwoch","correct":"a"},{"person":"Donnerstag","correct":"f"},{"person":"Freitag","correct":"c"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Mitarbeiter","gender":"m","text":"Guten Tag, eine Karte? Tageskarte oder nur eine Stunde?"},{"speaker":"Kunde","gender":"m","text":"Ja, eine Tageskarte bitte, Erwachsener. Muss ich etwas extra zahlen?"},{"speaker":"Mitarbeiter","gender":"m","text":"Nur Schwimmen kostet 5 Euro 50, mit Sauna 12 Euro. Nichts zahlen geht leider nicht."},{"speaker":"Kunde","gender":"m","text":"Nur Schwimmen, ohne Sauna, danke. Also 5 Euro 50."},{"speaker":"Mitarbeiter","gender":"m","text":"Genau, 5 Euro 50 bitte, zahlen Sie bar oder mit Karte?"}],"q":"Wie viel zahlt der Kunde?","opts":["5,50 Euro.","12 Euro.","Nichts."],"correct":0},{"lines":[{"speaker":"Tochter","gender":"f","text":"Papa, ich will von der Rutsche! Bitte, nur einmal, ich habe keine Angst."},{"speaker":"Vater","gender":"m","text":"Wie alt bist du jetzt, 5? Du bist noch zu klein. Die Rutsche ist nicht kaputt, aber du darfst noch nicht alleine."},{"speaker":"Tochter","gender":"f","text":"Aber Tim ist 6, der durfte! Warum darf ich nicht?"},{"speaker":"Vater","gender":"m","text":"Genau, erst ab 6 Jahren, du musst noch ein Jahr warten, weil du zu klein bist."},{"speaker":"Tochter","gender":"f","text":"Schade, dann gehe ich ins Kinderbecken."}],"q":"Warum darf das Mädchen nicht?","opts":["Sie hat Angst.","Sie ist zu klein.","Die Rutsche ist kaputt."],"correct":1},{"lines":[{"speaker":"Schwimmlehrer","gender":"m","text":"Heute lernen wir den Kraul-Stil. Letzte Woche war Brustschwimmen, nächste Woche Rückenschwimmen."},{"speaker":"Schüler","gender":"m","text":"Kraul ist mir zu schwer. Können wir Brustschwimmen? Oder Rückenschwimmen?"},{"speaker":"Schwimmlehrer","gender":"m","text":"Brust hast du letzte Woche gelernt. Rückenschwimmen machen wir nächste Woche. Heute Kraul."},{"speaker":"Schüler","gender":"m","text":"Okay, dann Kraul, aber bitte langsam erklären."},{"speaker":"Schwimmlehrer","gender":"m","text":"Kein Problem, wir üben Schritt für Schritt."}],"q":"Was lernen sie heute?","opts":["Brustschwimmen.","Rückenschwimmen.","Kraul."],"correct":2},{"lines":[{"speaker":"Bademeisterin","gender":"f","text":"Bitte langsamer! Hier ist kein Rennen, schwimmen ist okay, aber nicht rennen."},{"speaker":"Kind","gender":"m","text":"Entschuldigung, darf ich den Ball mit ins große Becken nehmen?"},{"speaker":"Bademeisterin","gender":"f","text":"Nein, keine Bälle im großen Becken. Die sind nur im Kinderbecken erlaubt. Schwimmflügel tragen darfst du."},{"speaker":"Kind","gender":"m","text":"Verstehe, also nicht rennen und keinen Ball im großen Becken."},{"speaker":"Bademeisterin","gender":"f","text":"Genau, danke, dann bleibt es sicher für alle."}],"q":"Was darf das Kind nicht?","opts":["Rennen oder Ball spielen im großen Becken.","Schwimmen.","Schwimmflügel tragen."],"correct":0},{"lines":[{"speaker":"Mann","gender":"m","text":"Ich gehe noch in die Sauna. Du kannst im Becken warten."},{"speaker":"Frau","gender":"f","text":"Wie lange dauert das? 15 Minuten, eine Stunde oder zwei Stunden?"},{"speaker":"Mann","gender":"m","text":"Drei mal 15 Minuten, mit Pausen. Also etwa eine Stunde, nicht zwei Stunden."},{"speaker":"Frau","gender":"f","text":"Okay, dann schwimme ich noch eine Runde. In einer Stunde sehen wir uns am Eingang."},{"speaker":"Mann","gender":"m","text":"Gut, bis dann."}],"q":"Wie lange ist der Mann in der Sauna?","opts":["15 Minuten.","Zwei Stunden.","Eine Stunde."],"correct":2}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Herrn Berg, einem Bademeister. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporter","gender":"m","text":"Herr Berg, Sie sind seit 18 Jahren Bademeister im Hallenbad. Wie sind Sie zu diesem Beruf gekommen?"},{"speaker":"Berg","gender":"m","text":"Eigentlich bin ich Profi-Schwimmer gewesen — in der Jugend. Aber für Olympia hat es nicht gereicht. Mit 25 habe ich aufgehört zu trainieren und Rettungsschwimmer gelernt. So wurde ich Bademeister."},{"speaker":"Reporter","gender":"m","text":"Wie ist Ihr typischer Arbeitstag?"},{"speaker":"Berg","gender":"m","text":"Schichten. Frühschicht ab 6 Uhr morgens — wir öffnen um 7. Spätschicht bis 22 Uhr. Während der Arbeit beobachte ich das Wasser, helfe wenn jemand Probleme hat. Ich gebe auch Schwimmunterricht für Kinder."},{"speaker":"Reporter","gender":"m","text":"Hatten Sie schon Notfälle?"},{"speaker":"Berg","gender":"m","text":"Ja, einige in 18 Jahren. Vor allem ältere Menschen, denen plötzlich schlecht wird. Auch Kinder, die zu mutig sind und ins tiefe Wasser gehen. Aber zum Glück nie ein Todesfall — wir reagieren schnell."},{"speaker":"Reporter","gender":"m","text":"Schwimmen Sie selbst noch viel?"},{"speaker":"Berg","gender":"m","text":"Privat sehr wenig. Den ganzen Tag bin ich am Becken. Wenn ich frei habe, gehe ich lieber in den Wald wandern. Mein Sport ist heute Joggen."},{"speaker":"Reporter","gender":"m","text":"Was raten Sie Eltern für Kinder im Schwimmbad?"},{"speaker":"Berg","gender":"m","text":"Erstens: Schwimmen lernen ist sehr wichtig — am besten früh anfangen. Zweitens: Kinder unter 8 nie alleine im Wasser lassen. Drittens: Schwimmflügel sind kein Ersatz für Aufsicht."}],"items":[{"q":"In 18 Jahren ist nie etwas Schlimmes passiert.","correct":"nein"},{"q":"Herr Berg war in der Jugend Profi-Schwimmer.","correct":"ja"},{"q":"Privat schwimmt er sehr viel.","correct":"nein"},{"q":"Sein heutiger Sport ist Joggen.","correct":"ja"},{"q":"Schwimmflügel sind ein guter Ersatz für Aufsicht.","correct":"nein"}]}]};
